CREATE OR REPLACE FUNCTION public.gerenciar_perfil() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IN ('authenticated','anon') AND (new.papel IS DISTINCT FROM old.papel OR new.email IS DISTINCT FROM old.email OR new.id IS DISTINCT FROM old.id OR new.pipedrive_user_id IS DISTINCT FROM old.pipedrive_user_id) THEN RAISE EXCEPTION 'Campos protegidos'; END IF; RETURN new; END $$;